function mix(hex: string, other: string, t: number) {
  const p = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const a = p(hex), b = p(other);
  return "#" + a.map((v, i) => Math.round(v + (b[i] - v) * t).toString(16).padStart(2, "0")).join("").toUpperCase();
}

export type Paint = { fg: string; lane: string; acc?: string; et?: string; out?: string; tile?: string; uid?: string };
/** Fills a template's placeholders. */
export function paint(markup: string, p: Paint): string {
  const acc = p.acc ?? BRAND.amber;
  const tile = p.tile ?? BRAND.navy;
  return markup
    .split("%FG%").join(p.fg)
    .split("%LANE%").join(p.lane)
    .split("%ACC%").join(acc)
    .split("%ET%").join(p.et ?? acc)
    .split("%OUT%").join(p.out ?? p.fg)
    .split("%TILE_A%").join(mix(tile, "#FFFFFF", 0.1))
    .split("%TILE_B%").join(mix(tile, "#000000", 0.16))
    .split("%UID%").join(p.uid ?? "a");
}

/** Colours for a mark on a light or dark background. Yellow stays yellow; on white it is one step deeper (#EAB308) so it reads as the same yellow. */
export function tonePaint(tone: "onLight" | "onDark"): Paint {
  return tone === "onDark"
    ? { fg: BRAND.white, lane: BRAND.navy, acc: BRAND.amber, out: BRAND.white }
    : { fg: BRAND.navy, lane: BRAND.amber, acc: BRAND.amberOnLight, out: BRAND.navy };
}
